<!--
 * 站内通知列表页组件
 *
 * @path apps/message-web/src/views/notification/index.vue
 * @author ydsz-team
 * @since 1.0.0
 * @modified 4.1.0 由脚手架 CRUD 重写为消费契约 API（inbox/countUnread/markRead/markAllRead/deleteApi/recall）。
 * @modified 4.2.0 新增「@提及」列，消费 MsgNotificationVO.mentionUserIds（由评论等业务侧 @提及产生）。
-->
<script lang="ts" setup>
/**
 * 站内通知（列表页）
 * <p>消费后端契约 NotificationController（src/api/notification.ts，auto-generated by bash/gen-contract.py）：
 * inbox() 分页查询收件箱并展示 countUnread() 未读数；支持「全部已读」markAllRead、单条标记已读 markRead、
 * 「删除」deleteApi([id])、「撤回」recall({id})；工具栏「发送通知」打开 notification-form.vue。
 *
 * @author ydsz-team
 * @since 1.0.0
 */
import type { VxeTableGridOptions } from '@ydsz/plugins/vxe-table';

import { Page, useYDSZModal } from '@ydsz/common-ui';

import { ElButton, ElMessage, ElMessageBox, ElTag } from 'element-plus';
import { h, onMounted, ref } from 'vue';

import { useYDSZVxeGrid } from '#/adapter/vxe-table';
import { countUnread, deleteApi, inbox, markAllRead, markRead, recall } from '#/api/notification';
import type { MsgNotificationVO } from '#/api/models';

import NotificationForm from './notification-form.vue';

defineOptions({ name: 'NotificationManagement' });

/** 未读通知数 */
const unreadCount = ref(0);

/** 加载未读数 */
async function loadUnread() {
  try {
    unreadCount.value = await countUnread();
  } catch {
    // 错误提示由请求拦截器统一处理
  }
}

onMounted(loadUnread);

const gridOptions: VxeTableGridOptions<MsgNotificationVO> = {
  columns: [
    { type: 'seq', width: 50, title: '序号' },
    { field: 'title', title: '标题', width: 200 },
    { field: 'category', title: '分类', width: 100 },
    { field: 'level', title: '级别', width: 90 },
    {
      field: 'readStatus',
      title: '已读',
      width: 80,
      slots: {
        default: ({ row }) =>
          h(ElTag, { type: row.readStatus === 1 ? 'success' : 'info' }, () =>
            row.readStatus === 1 ? '已读' : '未读',
          ),
      },
    },
    {
      field: 'recallStatus',
      title: '撤回',
      width: 90,
      slots: {
        default: ({ row }) =>
          h(ElTag, { type: row.recallStatus ? 'warning' : 'info' }, () => row.recallStatus ?? '-'),
      },
    },
    {
      field: 'mentionUserIds',
      title: '@提及',
      width: 150,
      slots: {
        default: ({ row }) =>
          row.mentionUserIds
            ? h(ElTag, { type: 'warning', effect: 'light' }, () => `@${row.mentionUserIds}`)
            : h('span', { class: 'text-gray-400' }, '-'),
      },
    },
    { field: 'createdAt', title: '创建时间', width: 170 },
    {
      field: 'action',
      title: '操作',
      width: 190,
      fixed: 'right',
      slots: {
        default: ({ row }) =>
          h('div', { class: 'flex gap-1' }, [
            ...(row.readStatus === 1
              ? []
              : [
                  h(
                    ElButton,
                    {
                      size: 'small',
                      link: true,
                      type: 'primary',
                      onClick: () => handleMarkRead(row),
                    },
                    () => '已读',
                  ),
                ]),
            h(
              ElButton,
              { size: 'small', link: true, type: 'warning', onClick: () => handleRecall(row) },
              () => '撤回',
            ),
            h(
              ElButton,
              { size: 'small', link: true, type: 'danger', onClick: () => handleDelete(row) },
              () => '删除',
            ),
          ]),
      },
    },
  ],
  height: 'auto',
  pagerConfig: { pageSize: 20, pageSizes: [10, 20, 50, 100] },
  proxyConfig: {
    ajax: {
      query: async (_page, formValues) => {
        const res = await inbox({ query: { ...formValues } });
        return { items: res.data ?? [], total: res.total ?? 0 };
      },
    },
  },
  toolbarConfig: { custom: true, refresh: { code: 'query' }, search: true, zoom: true },
  formConfig: {
    enabled: true,
    items: [
      {
        field: 'category',
        title: '分类',
        itemRender: { name: 'Input', props: { placeholder: '分类' } },
      },
      {
        field: 'level',
        title: '级别',
        itemRender: { name: 'Input', props: { placeholder: '级别' } },
      },
    ],
  },
};

const [Grid, gridApi] = useYDSZVxeGrid({ gridOptions });

const [NotificationFormModal, notificationFormApi] = useYDSZModal({
  connectedComponent: NotificationForm,
});

function handleSend() {
  notificationFormApi.open();
}

async function handleMarkRead(row: MsgNotificationVO) {
  if (!row.id) return;
  try {
    await markRead({ id: row.id });
    ElMessage.success('已标记为已读');
    gridApi.query();
    await loadUnread();
  } catch {
    // 错误提示由请求拦截器统一处理
  }
}

async function handleMarkAllRead() {
  try {
    await markAllRead();
    ElMessage.success('已全部标记为已读');
    gridApi.query();
    await loadUnread();
  } catch {
    // 错误提示由请求拦截器统一处理
  }
}

async function handleRecall(row: MsgNotificationVO) {
  if (!row.id) return;
  try {
    await ElMessageBox.confirm(`确定撤回通知「${row.title}」吗？`, '撤回确认', { type: 'warning' });
    await recall({ id: row.id });
    ElMessage.success('撤回成功');
    gridApi.query();
    await loadUnread();
  } catch {
    // 用户取消或请求失败
  }
}

async function handleDelete(row: MsgNotificationVO) {
  try {
    await ElMessageBox.confirm(`确定删除通知「${row.title}」吗？`, '删除确认', { type: 'warning' });
    if (row.id) await deleteApi([row.id]);
    ElMessage.success('删除成功');
    gridApi.query();
    await loadUnread();
  } catch {
    // 用户取消或请求失败
  }
}
</script>
<template>
  <Page auto-content-height>
    <div class="mb-3 flex items-center gap-2">
      <ElTag type="danger" effect="plain">未读：{{ unreadCount }}</ElTag>
      <ElButton size="small" type="primary" plain @click="handleMarkAllRead">全部已读</ElButton>
    </div>
    <Grid table-title="收件箱">
      <template #toolbar-tools>
        <ElButton type="primary" @click="handleSend">发送通知</ElButton>
      </template>
    </Grid>
    <NotificationFormModal @success="gridApi.query()" />
  </Page>
</template>
